sp_widget.css:
.media-list {
  padding: 16px;
  background: transparent;
}

/* header row */
.media-list .sp-row { display:flex; align-items:center; justify-content:space-between; margin-bottom:12px; }
.media-list .sp-heading { margin:0; font-size:18px; }

/* search */
.media-list .search-wrap { max-width:320px; width:100%; }
.media-list input.form-control { width:100%; }

/* table */
.media-list table { width:100%; border-collapse: collapse; }
.media-list th { text-align:left; padding:8px 12px; font-weight:600; }
.media-list td { padding:8px 12px; vertical-align:middle; }

/* poster */
.media-poster {
  width:80px;
  height:120px;
  object-fit:cover;
  border-radius:4px;
  box-shadow: 0 1px 2px rgba(0,0,0,0.15);
}

/* título */
.media-title { font-weight:600; max-width:320px; word-break:break-word; }

/* responsive */
@media (max-width: 600px) {
  .media-poster { width:60px; height:90px; }
  .media-list { padding:8px; }
  .media-list th, .media-list td { padding:6px; font-size:13px; }
}

sp_widget.script:
(function() {
  data.filmes = [];

  var gr = new GlideRecord('x_1795292_netflix_media');
  gr.orderByDesc('sys_created_on');
  gr.query();

  while (gr.next()) {
    data.filmes.push({
      sys_id: gr.getValue('sys_id'),
      title: gr.getValue('title'),
      type: gr.getValue('type'),
      year: gr.getValue('year'),
      poster_url: gr.getValue('poster') || '',
      description: gr.getValue('short_description') || gr.getValue('description') || ''
    });
  }

  data.totalReturned = data.filmes.length;
  data.hasMore = false; 
})();
